// Request bodies come from the server's OpenAPI (schema.d.ts, generated by `npm run gen:api`).
// Response shapes are the dicts `h3_48gb/studio/ops.py` builds; they are written out here.
import type { components } from "./schema";

export type ProjectCreate = components["schemas"]["ProjectCreate"];
export type ProjectPatch = components["schemas"]["ProjectPatch"];
export type CastCreate = components["schemas"]["CastCreate"];
export type SceneIn = components["schemas"]["SceneIn"];
export type ScenePatch = components["schemas"]["ScenePatch"];
export type ProposeRequest = components["schemas"]["ProposeRequest"];
export type ApplyRequest = components["schemas"]["ApplyRequest"];
export type PlanRequest = components["schemas"]["PlanRequest"];

export type Project = {
  id: string;
  revision: number;
  title: string;
  frame_format: "16:9" | "9:16";
  idea_text: string;
  style_block: string;
  created_at: string;
};
export type ProjectListItem = Project & { scenes_total: number; scenes_done: number };

export type Asset = { id: string; kind: string; sha256: string; bytes: number; mime: string; url: string };

export type CastMember = {
  id: string;
  tag: string;
  description_ru: string;
  description_en: string;
  portrait_phrase: string;
  assets: { asset_id: string; role: "image"; ord: number; url: string }[];
};

/** What the server ANSWERS. `auto`: a `prev_last_frame` derived from the order, not named by the
 *  owner. On input the field is forbidden (400): see `toSceneIn`. */
export type SourceFrame = { kind: "none" | "prev_last_frame" | "asset"; scene_id: string | null; asset_id: string | null; auto: boolean };

export type Scene = {
  id: string;
  idx: number;
  revision: number;
  state_version: number;
  /** И1a: +1 on every change of any editable field — the version O7/O8 check. */
  edit_version: number;
  mode: "from_frame" | "refs" | "text";
  action_text: string;
  performance_text: string;
  sound_text: string;
  music_text: string;
  state_in_text: string;
  state_out_text: string;
  requested_s: number;
  frames: number;
  duration_s: number;
  seed: number;
  source_frame: SourceFrame;
  refs: string[];
  review_state: string;
  approved_sketch_take_id: string | null;
  approved_final_take_id: string | null;
};

export type Finding = { rule: string; severity: "error" | "warning" | "info"; scene_id: string; field: string | null; message: string };
export type LintMap = Record<string, Finding[]>;

export type ProposedScene = Omit<SceneIn, "scene_id">;
export type Proposal = {
  proposal_id: string;
  scenes: ProposedScene[];
  durations: { frames: number; duration_s: number }[];
  dropped_tags: string[];
};
export type ScenesResult = { project: Project; scenes: Scene[]; diff: Record<string, string[]>; lint: LintMap };
export type SceneResult = { scene: Scene; cascade: string[]; lint: Finding[] };

export type TaskStatus =
  | "queued" | "blocked" | "waiting_gpu" | "waiting_ready" | "submitting" | "submit_unknown"
  | "running" | "cancelling" | "downloading" | "verifying" | "succeeded" | "failed" | "cancelled";

/** O13 — `h3_48gb/studio/tasks.py: task_out`. */
export type Task = {
  id: string;
  kind: "image" | "render" | "assemble" | "extract_frame";
  project_id: string;
  status: TaskStatus;
  template: string | null;
  wait_reason: string | null;
  progress_step: number | null;
  progress_total: number | null;
  error: string | null;
  attempts: number;
  engine_stop: string | null;
  engine_version: string | null;
  template_sha256: string | null;
  cancel_requested: boolean;
  depends_on_task_id: string | null;
  result_asset_id: string | null;
  result_url: string | null;
  created_at: string;
  updated_at: string;
};

export type PlanItem = {
  kind: "image" | "render";
  scene_id: string | null;
  template: string;
  estimate_s: number;
  status: "ready" | "blocked" | "invalid";
  reasons: string[];
  prompt?: string;
  width?: number;
  height?: number;
  seed?: number;
  steps?: number;
  [extra: string]: unknown;
};

/** O10 — `h3_48gb/studio/plans.py`. */
export type Plan = {
  plan_id: string;
  expires_at: string;
  kind: "image" | "render";
  items: PlanItem[];
  total_s: number;
  checkpoint_switches: { from: string | null; to: string; seconds: number }[];
  lint: LintMap;
  blocked: string[];
  invalid: string[];
};

export type Snapshot = {
  project: Project;
  scenes: Scene[];
  cast: CastMember[];
  takes: unknown[];
  tasks: Task[];
  last_seq: number;
};

export type ApiErrorBody = { error: { code: string; message: string; detail: Record<string, unknown> } };
